/** Detects encrypted private saves so importers can direct players to the official export. */
export const GAME_EXPORT_REQUIRED_MESSAGE = 'Only the official in-game External Tools Export is supported. First tap your Player ID five times to create your first export and reveal the export controls. Then open Settings > Toggles > External Tools Export and choose Manual Export, then upload the exported JSON file. Attempting to bypass save-file encryption violates The Tower Terms of Service.'

export function isEncryptedSave(bytes: Uint8Array): boolean {
  return bytes.length >= 4 && bytes[0] === 0x54 && bytes[1] === 0x44 && bytes[2] === 0x53 && bytes[3] === 0x31
}
